Here are the unit tests for the `Calculator` class:

```python
import unittest

class Calculator:
    def multiply(self, x, y):
        return x * y

class TestCalculator(unittest.TestCase):
    def setUp(self):
        self.calc = Calculator()

    def test_multiply_positive_integers(self):
        self.assertEqual(self.calc.multiply(2, 3), 6)

    def test_multiply_negative_integers(self):
        self.assertEqual(self.calc.multiply(-2, 3), -6)

    def test_multiply_floats(self):
        self.assertAlmostEqual(self.calc.multiply(1.5, 2), 3.0)

    def test_multiply_by_zero(self):
        self.assertEqual(self.calc.multiply(5, 0), 0)

    def test_multiply_negative_floats(self):
        self.assertAlmostEqual(self.calc.multiply(-1.5, -2), 3.0)

if __name__ == '__main__':
    unittest.main()
```
